export const databaseContent = "-- UNDIGITAL MySQL 8 schema\n-- Requires MySQL 8.0.16+ for enforced CHECK constraints and JSON defaults.\n\nSET NAMES utf8mb4;\nSET time_zone = '+00:00';\nSET FOREIGN_KEY_CHECKS = 0;\n\nCREATE DATABASE IF NOT EXISTS undigital\n  CHARACTER SET utf8mb4\n  COLLATE utf8mb4_unicode_ci;\nUSE undigital;\n\nCREATE TABLE users (\n  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  public_id CHAR(36) NOT NULL,\n  role ENUM('super_admin', 'customer') NOT NULL DEFAULT 'customer',\n  name VARCHAR(120) NOT NULL,\n  email VARCHAR(190) NOT NULL,\n  password_hash VARCHAR(255) NULL,\n  avatar_url VARCHAR(500) NULL,\n  email_verified_at DATETIME NULL,\n  is_active TINYINT(1) NOT NULL DEFAULT 1,\n  last_login_at DATETIME NULL,\n  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_users_public_id (public_id),\n  UNIQUE KEY uq_users_email (email),\n  KEY idx_users_role_active (role, is_active)\n) ENGINE=InnoDB;\n\nCREATE TABLE oauth_accounts (\n  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  user_id BIGINT UNSIGNED NOT NULL,\n  provider ENUM('google') NOT NULL,\n  provider_user_id VARCHAR(191) NOT NULL,\n  provider_email VARCHAR(190) NULL,\n  profile_json JSON NULL,\n  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_oauth_provider_identity (provider, provider_user_id),\n  KEY idx_oauth_user (user_id),\n  CONSTRAINT fk_oauth_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE\n) ENGINE=InnoDB;\n\nCREATE TABLE auth_sessions (\n  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  user_id BIGINT UNSIGNED NOT NULL,\n  token_hash CHAR(64) NOT NULL,\n  csrf_hash CHAR(64) NOT NULL,\n  ip_hash CHAR(64) NULL,\n  user_agent VARCHAR(500) NULL,\n  expires_at DATETIME NOT NULL,\n  last_seen_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  revoked_at DATETIME NULL,\n  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_auth_sessions_token (token_hash),\n  KEY idx_sessions_user_expiry (user_id, expires_at),\n  KEY idx_sessions_expiry_revoked (expires_at, revoked_at),\n  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE\n) ENGINE=InnoDB;\n\nCREATE TABLE events (\n  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  public_id CHAR(36) NOT NULL,\n  owner_id BIGINT UNSIGNED NOT NULL,\n  slug VARCHAR(120) NOT NULL,\n  title VARCHAR(180) NOT NULL,\n  groom_name VARCHAR(120) NOT NULL,\n  bride_name VARCHAR(120) NOT NULL,\n  event_type VARCHAR(80) NOT NULL DEFAULT 'Pernikahan',\n  religion VARCHAR(80) NULL,\n  starts_at DATETIME NOT NULL,\n  timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Jakarta',\n  status ENUM('draft', 'published', 'archived') NOT NULL DEFAULT 'draft',\n  cover_media_id BIGINT UNSIGNED NULL,\n  published_at DATETIME NULL,\n  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  deleted_at DATETIME NULL,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_events_public_id (public_id),\n  UNIQUE KEY uq_events_slug (slug),\n  KEY idx_events_owner_status (owner_id, status, deleted_at),\n  KEY idx_events_public_lookup (slug, status, deleted_at),\n  KEY idx_events_date (starts_at),\n  CONSTRAINT fk_events_owner FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE RESTRICT,\n  CONSTRAINT chk_events_slug CHECK (slug REGEXP '^[a-z0-9]+(?:-[a-z0-9]+)*$')\n) ENGINE=InnoDB;\n\nCREATE TABLE event_editor_tabs (\n  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  event_id BIGINT UNSIGNED NOT NULL,\n  tab_key ENUM(\n    'info_cover',\n    'couple_profiles',\n    'schedule_map',\n    'gallery',\n    'love_story',\n    'digital_gifts',\n    'settings_prayers'\n  ) NOT NULL,\n  schema_version SMALLINT UNSIGNED NOT NULL DEFAULT 1,\n  content JSON NOT NULL,\n  revision BIGINT UNSIGNED NOT NULL DEFAULT 1,\n  updated_by BIGINT UNSIGNED NULL,\n  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_event_editor_tab (event_id, tab_key),\n  KEY idx_editor_updated_by (updated_by),\n  KEY idx_editor_event_revision (event_id, revision),\n  CONSTRAINT fk_editor_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,\n  CONSTRAINT fk_editor_user FOREIGN KEY (updated_by) REFERENCES users(id) ON DELETE SET NULL,\n  CONSTRAINT chk_editor_content_object CHECK (JSON_TYPE(content) = 'OBJECT')\n) ENGINE=InnoDB;\n\nCREATE TABLE media_files (\n  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  public_id CHAR(36) NOT NULL,\n  event_id BIGINT UNSIGNED NOT NULL,\n  uploaded_by BIGINT UNSIGNED NULL,\n  media_kind ENUM('cover', 'groom', 'bride', 'gallery', 'music') NOT NULL,\n  relative_path VARCHAR(500) NOT NULL,\n  original_name VARCHAR(255) NULL,\n  mime_type ENUM('image/jpeg', 'audio/mpeg') NOT NULL,\n  byte_size INT UNSIGNED NOT NULL,\n  width SMALLINT UNSIGNED NULL,\n  height SMALLINT UNSIGNED NULL,\n  sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,\n  sha256 CHAR(64) NOT NULL,\n  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_media_public_id (public_id),\n  UNIQUE KEY uq_media_path (relative_path),\n  KEY idx_media_event_kind_order (event_id, media_kind, sort_order),\n  KEY idx_media_uploader (uploaded_by),\n  CONSTRAINT fk_media_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,\n  CONSTRAINT fk_media_uploader FOREIGN KEY (uploaded_by) REFERENCES users(id) ON DELETE SET NULL,\n  CONSTRAINT chk_media_size CHECK (byte_size > 0)\n) ENGINE=InnoDB;\n\nALTER TABLE events\n  ADD CONSTRAINT fk_events_cover_media\n  FOREIGN KEY (cover_media_id) REFERENCES media_files(id) ON DELETE SET NULL;\n\nCREATE TABLE invitation_guests (\n  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  event_id BIGINT UNSIGNED NOT NULL,\n  guest_token CHAR(32) NOT NULL,\n  display_name VARCHAR(160) NOT NULL,\n  phone VARCHAR(32) NULL,\n  party_size SMALLINT UNSIGNED NOT NULL DEFAULT 1,\n  source VARCHAR(80) NULL,\n  first_opened_at DATETIME NULL,\n  last_opened_at DATETIME NULL,\n  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_guest_token (guest_token),\n  KEY idx_guests_event_name (event_id, display_name),\n  CONSTRAINT fk_guests_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,\n  CONSTRAINT chk_guest_party_size CHECK (party_size BETWEEN 1 AND 20)\n) ENGINE=InnoDB;\n\nCREATE TABLE rsvp_guestbook (\n  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  public_id CHAR(36) NOT NULL,\n  event_id BIGINT UNSIGNED NOT NULL,\n  guest_id BIGINT UNSIGNED NULL,\n  guest_name VARCHAR(160) NOT NULL,\n  phone VARCHAR(32) NULL,\n  attendance ENUM('attending', 'not_attending', 'maybe') NOT NULL,\n  attendee_count SMALLINT UNSIGNED NOT NULL DEFAULT 1,\n  message TEXT NULL,\n  is_approved TINYINT(1) NOT NULL DEFAULT 1,\n  ip_hash CHAR(64) NULL,\n  user_agent VARCHAR(500) NULL,\n  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  UNIQUE KEY uq_rsvp_public_id (public_id),\n  KEY idx_rsvp_event_feed (event_id, is_approved, created_at),\n  KEY idx_rsvp_guest (guest_id),\n  CONSTRAINT fk_rsvp_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE CASCADE,\n  CONSTRAINT fk_rsvp_guest FOREIGN KEY (guest_id) REFERENCES invitation_guests(id) ON DELETE SET NULL,\n  CONSTRAINT chk_attendee_count CHECK (attendee_count BETWEEN 0 AND 20)\n) ENGINE=InnoDB;\n\nCREATE TABLE audit_logs (\n  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,\n  actor_user_id BIGINT UNSIGNED NULL,\n  event_id BIGINT UNSIGNED NULL,\n  action VARCHAR(80) NOT NULL,\n  entity_type VARCHAR(80) NOT NULL,\n  entity_id VARCHAR(64) NULL,\n  metadata JSON NULL,\n  ip_hash CHAR(64) NULL,\n  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (id),\n  KEY idx_audit_actor_time (actor_user_id, created_at),\n  KEY idx_audit_event_time (event_id, created_at),\n  CONSTRAINT fk_audit_actor FOREIGN KEY (actor_user_id) REFERENCES users(id) ON DELETE SET NULL,\n  CONSTRAINT fk_audit_event FOREIGN KEY (event_id) REFERENCES events(id) ON DELETE SET NULL\n) ENGINE=InnoDB;\n\n-- Rate limiting without retaining raw IP addresses.\nCREATE TABLE rate_limits (\n  bucket_key CHAR(64) NOT NULL,\n  hits INT UNSIGNED NOT NULL DEFAULT 1,\n  window_started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  expires_at DATETIME NOT NULL,\n  PRIMARY KEY (bucket_key),\n  KEY idx_rate_limits_expiry (expires_at)\n) ENGINE=InnoDB;\n\nSET FOREIGN_KEY_CHECKS = 1;\n";

export const rootHtaccessContent = "Options -Indexes -MultiViews\nServerSignature Off\n\n<IfModule mod_headers.c>\n  Header always set X-Frame-Options \"SAMEORIGIN\"\n  Header always set X-Content-Type-Options \"nosniff\"\n  Header always set X-XSS-Protection \"1; mode=block\"\n  Header always set Referrer-Policy \"strict-origin-when-cross-origin\"\n  Header always set Permissions-Policy \"camera=(), microphone=(), geolocation=(self), payment=()\"\n  Header always set Cross-Origin-Opener-Policy \"same-origin-allow-popups\"\n  Header always set Content-Security-Policy \"default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'self'; form-action 'self'; img-src 'self' data: blob: https://maps.googleapis.com https://*.googleusercontent.com; media-src 'self' blob: https://*.soundcloud.com; connect-src 'self' https://*.googleapis.com https://*.soundcloud.com; frame-src 'self' https://www.youtube.com https://www.youtube-nocookie.com https://w.soundcloud.com https://www.google.com https://maps.google.com; script-src 'self' https://www.youtube.com https://w.soundcloud.com; style-src 'self' 'unsafe-inline'\"\n</IfModule>\n\n<IfModule mod_rewrite.c>\n  RewriteEngine On\n\n  # Block dotfiles and hidden directories, while Apache may still read .htaccess.\n  RewriteRule \"(^|/)\\.\" - [F,L]\n\n  # Never expose source, configuration, database, logs, or dependencies.\n  RewriteRule ^(?:app|database|docs|tests|vendor|node_modules)(?:/|$) - [F,L,NC]\n  RewriteRule \\.(?:env|ini|log|sql|sqlite|bak|dist|yml|yaml|lock|md)$ - [F,L,NC]\n\n  # Preserve the REST front controller and physical public assets.\n  RewriteRule ^api/?$ api.php [END,QSA]\n  RewriteCond %{REQUEST_FILENAME} -f [OR]\n  RewriteCond %{REQUEST_FILENAME} -d\n  RewriteRule ^ - [END]\n\n  # History API fallback for /, /login, /admin, /studio and public slugs.\n  RewriteRule ^ index.html [END]\n</IfModule>\n\n<FilesMatch \"^(?:\\.env|\\.git|\\.htaccess|composer\\.(?:json|lock)|package(?:-lock)?\\.json|schema\\.sql)$\">\n  Require all denied\n</FilesMatch>\n\n<FilesMatch \"\\.(?:php~|phar|phtml|inc|sh|cgi|pl|py|rb|conf|config)$\">\n  Require all denied\n</FilesMatch>\n\n# api.php is the only publicly executable PHP file.\n<Files \"api.php\">\n  Require all granted\n</Files>\n\n<IfModule mod_deflate.c>\n  AddOutputFilterByType DEFLATE text/html text/plain text/css text/javascript application/javascript application/json image/svg+xml\n</IfModule>\n\n<IfModule mod_expires.c>\n  ExpiresActive On\n  ExpiresByType text/html \"access plus 0 seconds\"\n  ExpiresByType application/json \"access plus 0 seconds\"\n  ExpiresByType text/css \"access plus 1 year\"\n  ExpiresByType application/javascript \"access plus 1 year\"\n  ExpiresByType image/jpeg \"access plus 1 year\"\n  ExpiresByType audio/mpeg \"access plus 1 year\"\n  ExpiresByType font/woff2 \"access plus 1 year\"\n</IfModule>\n\n<IfModule mod_headers.c>\n  <FilesMatch \"\\.(?:css|js|jpg|jpeg|mp3|woff2)$\">\n    Header set Cache-Control \"public, max-age=31536000, immutable\"\n  </FilesMatch>\n  <FilesMatch \"^(?:index\\.html|api\\.php)$\">\n    Header set Cache-Control \"no-store, max-age=0\"\n  </FilesMatch>\n</IfModule>\n";

export const uploadsHtaccessContent = "Options -Indexes -ExecCGI\n\n<IfModule mod_mime.c>\n  RemoveHandler .php .php3 .php4 .php5 .php7 .php8 .phtml .phar .cgi .pl .py .rb .sh\n  RemoveType .php .php3 .php4 .php5 .php7 .php8 .phtml .phar .cgi .pl .py .rb .sh\n  AddType image/jpeg .jpg .jpeg\n  AddType audio/mpeg .mp3\n</IfModule>\n\n<IfModule mod_php.c>\n  php_flag engine off\n</IfModule>\n\n<IfModule mod_rewrite.c>\n  RewriteEngine On\n\n  # Deny hidden files, traversal-like names, double extensions, and executable payloads.\n  RewriteRule \"(^|/)\\.\" - [F,L]\n  RewriteRule \"\\.\\.(?:/|$)\" - [F,L]\n  RewriteRule \"\\.(?:php[0-9]?|phtml|phar|sh|cgi|pl|py|rb|js|html?|svg|xml)(?:\\.|$)\" - [F,L,NC]\n\n  # Exact public whitelist: only these paths and media types may be served.\n  RewriteRule ^(?:covers|couples|gallery)/[A-Za-z0-9_-]+\\.jpe?g$ - [END,NC]\n  RewriteRule ^music/[A-Za-z0-9_-]+\\.mp3$ - [END,NC]\n  RewriteRule ^ - [F,L]\n</IfModule>\n\n<FilesMatch \"\\.(?:php[0-9]?|phtml|phar|sh|cgi|pl|py|rb|js|html?|svg|xml|htaccess|env)$\">\n  Require all denied\n</FilesMatch>\n\n<IfModule mod_headers.c>\n  Header always set X-Content-Type-Options \"nosniff\"\n  Header always set Content-Security-Policy \"default-src 'none'; sandbox\"\n  Header always set Cross-Origin-Resource-Policy \"same-site\"\n  Header set Cache-Control \"public, max-age=31536000, immutable\"\n</IfModule>\n";
